import { parseAbi, decodeErrorResult } from 'viem';

// The revert data from the transaction
const revertData = "";

// Define the OffchainLookup error ABI
const OffchainLookupAbi = parseAbi([
    'error OffchainLookup(address sender, string[] urls, bytes callData, bytes4 callbackFunction, bytes extraData)'
]);

async function main() {
    try {
        // Decode the error data
        const decoded = decodeErrorResult({
            abi: OffchainLookupAbi,
            data: revertData as `0x${string}`
        });

        console.log('Decoded OffchainLookup:');
        console.log('------------------------');
        console.log('Sender:', decoded.args[0]);
        console.log('URLs:', decoded.args[1]);
        console.log('CallData:', decoded.args[2]);
        console.log('Callback Function:', decoded.args[3]);
        console.log('ExtraData:', decoded.args[4]);

        // Additional parsing of the callData if needed
        const callData = decoded.args[2];
        console.log('\nParsed CallData:');
        console.log('----------------');
        console.log('Raw CallData:', callData);

    } catch (error) {
        console.error('Error decoding OffchainLookup:', error);
    }
}

main().catch(console.error); 